"""Tests for depcycle.utils module."""

from __future__ import annotations

import sys
from pathlib import Path

import pytest

from depcycle.utils import get_stdlib_names, normalize_name, path_to_module_name


def test_get_stdlib_names_native(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setattr(sys, "stdlib_module_names", {"os", "sys", "custom"}, raising=False)
    names = get_stdlib_names()
    assert "os" in names
    assert "sys" in names
    assert "custom" in names


def test_get_stdlib_names_fallback(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setattr(sys, "stdlib_module_names", None, raising=False)
    names = get_stdlib_names()
    assert "os" in names
    assert "sys" in names
    assert "pathlib" in names
    assert "json" in names


def test_normalize_name() -> None:
    assert normalize_name("Foo_Bar.Baz-Qux") == "foo-bar-baz-qux"
    assert normalize_name("  depcycle--pkg..mod_a  ") == "depcycle-pkg-mod-a"


def test_path_to_module_name() -> None:
    root = Path("/workspace/myproject")

    # Regular file inside root
    file_path = Path("/workspace/myproject/foo/bar.py")
    assert path_to_module_name(file_path, root) == "foo.bar"

    # __init__.py file inside root
    init_path = Path("/workspace/myproject/foo/bar/__init__.py")
    assert path_to_module_name(init_path, root) == "foo.bar"

    # Root __init__.py
    root_init = Path("/workspace/myproject/__init__.py")
    assert path_to_module_name(root_init, root) is None

    # Outside root
    outside_file = Path("/workspace/other/bar.py")
    assert path_to_module_name(outside_file, root) is None
